using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.DependencyInjection;

namespace CryptoUploadService
{
    public class CryptoProcessor
    {
        private readonly byte[] _masterKey;
        private const int MaxFileSize = 10 * 1024 * 1024;

        public CryptoProcessor(byte[] masterKey)
        {
            _masterKey = masterKey ?? throw new ArgumentNullException(nameof(masterKey));
        }

        public (byte[] hash, byte[] encrypted) ProcessUpload(Stream inputStream, string fileName)
        {
            if (inputStream == null) throw new ArgumentNullException(nameof(inputStream));
            if (string.IsNullOrWhiteSpace(fileName)) throw new ArgumentException("Invalid filename");

            var sanitizedName = Path.GetFileName(fileName);
            if (sanitizedName != fileName)
                throw new ArgumentException("Path traversal detected");

            using var memStream = new MemoryStream();
            inputStream.CopyTo(memStream);
            var data = memStream.ToArray();

            if (data.Length > MaxFileSize)
                throw new InvalidOperationException("File too large");

            byte[] hash;
            using (var hmac = new HMACSHA256(_masterKey))
            {
                hash = hmac.ComputeHash(data);
            }

            var encrypted = EncryptData(data);
            return (hash, encrypted);
        }

        private byte[] EncryptData(byte[] plaintext)
        {
            using var aes = Aes.Create();
            aes.KeySize = 256;
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;
            aes.GenerateIV();

            using var deriveKey = new Rfc2898DeriveBytes(_masterKey, aes.IV, 100000, HashAlgorithmName.SHA256);
            aes.Key = deriveKey.GetBytes(32);

            using var encryptor = aes.CreateEncryptor();
            var ciphertext = encryptor.TransformFinalBlock(plaintext, 0, plaintext.Length);

            var result = new byte[aes.IV.Length + ciphertext.Length];
            Buffer.BlockCopy(aes.IV, 0, result, 0, aes.IV.Length);
            Buffer.BlockCopy(ciphertext, 0, result, aes.IV.Length, ciphertext.Length);
            return result;
        }
    }

    public class SecurityHeaderMiddleware
    {
        private readonly RequestDelegate _next;
        private readonly SecurityHeaderOptions _options;

        public SecurityHeaderMiddleware(RequestDelegate next, SecurityHeaderOptions options)
        {
            _next = next;
            _options = options;
        }

        public async Task InvokeAsync(HttpContext context)
        {
            var headers = context.Response.Headers;

            headers["X-Content-Type-Options"] = "nosniff";
            headers["X-XSS-Protection"] = "1; mode=block";
            headers["Referrer-Policy"] = "strict-origin-when-cross-origin";
            headers["Content-Security-Policy"] = BuildCsp();

            if (_options.FrameProtectionEnabled)
            {
                ApplyFrameProtection(headers, context);
            }

            await _next(context);
        }

        private void ApplyFrameProtection(IHeaderDictionary headers, HttpContext context)
        {
            var origin = context.Request.Headers["Origin"].FirstOrDefault();
            var referer = context.Request.Headers["Referer"].FirstOrDefault();

            if (!string.IsNullOrEmpty(origin) && _options.AllowedFrameAncestors.Contains(origin))
            {
                headers["X-Frame-Options"] = $"ALLOW-FROM {origin}";
            }
            else if (_options.FrameProtectionMode == FrameProtectionMode.Adaptive)
            {
                headers["X-Frame-Options"] = "SAMEORIGIN";
            }
            else
            {
                headers["X-Frame-Options"] = "DENY";
            }
        }

        private string BuildCsp()
        {
            var sb = new StringBuilder();
            sb.Append("default-src 'self'; ");
            sb.Append("script-src 'self'; ");
            sb.Append("style-src 'self' 'unsafe-inline'; ");
            sb.Append("img-src 'self' data:; ");
            sb.Append("frame-ancestors ");
            if (_options.AllowedFrameAncestors.Count > 0)
            {
                sb.Append(string.Join(" ", _options.AllowedFrameAncestors));
            }
            else
            {
                sb.Append("'self'");
            }
            sb.Append(";");
            return sb.ToString();
        }
    }

    public enum FrameProtectionMode
    {
        Strict,
        Adaptive
    }

    public class SecurityHeaderOptions
    {
        public bool FrameProtectionEnabled { get; set; } = true;
        public FrameProtectionMode FrameProtectionMode { get; set; } = FrameProtectionMode.Adaptive;
        public List<string> AllowedFrameAncestors { get; set; } = new();
    }

    public static class Program
    {
        public static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);
            builder.Services.AddControllers();

            var masterKey = RandomNumberGenerator.GetBytes(32);
            builder.Services.AddSingleton(new CryptoProcessor(masterKey));

            var app = builder.Build();

            var secOptions = new SecurityHeaderOptions
            {
                FrameProtectionEnabled = true,
                FrameProtectionMode = FrameProtectionMode.Adaptive,
                AllowedFrameAncestors = new List<string>()
            };

            app.UseMiddleware<SecurityHeaderMiddleware>(secOptions);
            app.MapControllers();
            app.Run();
        }
    }

    [ApiController]
    [Route("api/[controller]")]
    public class UploadController : ControllerBase
    {
        private readonly CryptoProcessor _processor;

        public UploadController(CryptoProcessor processor)
        {
            _processor = processor;
        }

        [HttpPost("process")]
        public IActionResult ProcessFile(IFormFile file)
        {
            if (file == null || file.Length == 0)
                return BadRequest("No file provided");

            try
            {
                using var stream = file.OpenReadStream();
                var (hash, encrypted) = _processor.ProcessUpload(stream, file.FileName);
                return Ok(new
                {
                    Hash = Convert.ToBase64String(hash),
                    EncryptedSize = encrypted.Length,
                    Status = "processed"
                });
            }
            catch (Exception ex)
            {
                return BadRequest(new { Error = ex.Message });
            }
        }

        [HttpGet("status")]
        public IActionResult GetStatus()
        {
            return Ok(new { Service = "CryptoUploadService", Status = "running" });
        }
    }
}
